/* @autogenerated */
package net.civeira.phylax.feature.observe.source;

import java.util.Arrays;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicLong;
import java.util.function.Function;
import java.util.stream.Collectors;

import jakarta.enterprise.context.ApplicationScoped;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import net.civeira.phylax.feature.observe.config.ObserveSettings;
import net.civeira.phylax.feature.observe.observedsource.domain.ObservedSource;
import net.civeira.phylax.feature.observe.observedsource.domain.gateway.ObservedSourceFilter;
import net.civeira.phylax.feature.observe.observedsource.domain.gateway.ObservedSourceQueryRepositoryGateway;

/**
 * Snapshot of the observed sources for the ingestion, which checks every event against it. There
 * are few sources, so the whole table is kept in memory.
 *
 * <p>
 * The reads never touch the database: they are called from the log handler and the exporters, maybe
 * while the same thread holds the only connection of a pool. The snapshot is reloaded in the
 * background, at startup, every 30 seconds and shortly after the synchronization changes a row.
 */
@ApplicationScoped
@RequiredArgsConstructor
@Slf4j
public class SourceRegistry {

  private static final long PERIOD_SECONDS = 30;

  /**
   * A source as the ingestion sees it.
   *
   * @param accepting enabled, its origin is enabled and it is not detached
   * @param scrubFields extra keys masked in its events (normalized as {@link ObserveSettings#keys})
   */
  public record Source(String uid, String code, String name, String originType, String ingestKey,
      boolean accepting, String minLevel, int sampleRate, List<String> allowedOrigins,
      Optional<Integer> retentionDays, Set<String> scrubFields) {}

  private final ObservedSourceQueryRepositoryGateway sources;

  private volatile Map<String, Source> byCode = Map.of();
  private volatile Map<String, Source> byKey = Map.of();
  private final AtomicBoolean pending = new AtomicBoolean();
  private final AtomicBoolean started = new AtomicBoolean();
  private final ScheduledExecutorService reloader =
      Executors.newSingleThreadScheduledExecutor(r -> {
        Thread thread = new Thread(r, "observe-sources");
        thread.setDaemon(true);
        return thread;
      });
  private final Map<String, AtomicLong> lastSeen = new ConcurrentHashMap<>();
  private final Map<String, AtomicLong> dropped = new ConcurrentHashMap<>();

  public Optional<Source> byCode(final String code) {
    return null == code ? Optional.empty() : Optional.ofNullable(byCode.get(code));
  }

  public Optional<Source> byKey(final String key) {
    if (null == key || key.isBlank()) {
      return Optional.empty();
    }
    return Optional.ofNullable(byKey.get(key));
  }

  public List<Source> all() {
    return List.copyOf(byCode.values());
  }

  /**
   * Loads the snapshot now and then every 30 seconds. Called at startup, outside any log call.
   */
  public void start() {
    reload();
    if (started.compareAndSet(false, true)) {
      reloader.scheduleWithFixedDelay(this::reloadQuietly, PERIOD_SECONDS, PERIOD_SECONDS,
          TimeUnit.SECONDS);
    }
  }

  public void stop() {
    reloader.shutdownNow();
  }

  /** Reloads in the background shortly after a change (once the transaction has committed). */
  public void invalidate() {
    if (pending.compareAndSet(false, true)) {
      reloader.schedule(() -> {
        pending.set(false);
        reloadQuietly();
      }, 1, TimeUnit.SECONDS);
    }
  }

  public void seen(final String code) {
    lastSeen.computeIfAbsent(code, k -> new AtomicLong()).set(System.currentTimeMillis());
  }

  public void drop(final String code) {
    dropped.computeIfAbsent(null == code ? "-" : code, k -> new AtomicLong()).incrementAndGet();
  }

  public Optional<Long> lastSeen(final String code) {
    return Optional.ofNullable(lastSeen.get(code)).map(AtomicLong::get);
  }

  public long dropped(final String code) {
    return Optional.ofNullable(dropped.get(code)).map(AtomicLong::get).orElse(0L);
  }

  /** Reads the whole table; only from the startup or the background thread. */
  public synchronized void reload() {
    List<Source> loaded =
        sources.list(ObservedSourceFilter.builder().build()).stream().map(this::toSource).toList();
    byCode =
        loaded.stream().collect(Collectors.toMap(Source::code, Function.identity(), (a, b) -> a));
    byKey = loaded.stream().filter(s -> null != s.ingestKey())
        .collect(Collectors.toMap(Source::ingestKey, Function.identity(), (a, b) -> a));
  }

  private void reloadQuietly() {
    try {
      reload();
    } catch (RuntimeException ex) {
      log.warn("Unable to reload the observed sources: {}", ex.getMessage());
    }
  }

  private Source toSource(final ObservedSource source) {
    boolean accepting =
        Boolean.TRUE.equals(source.isEnabled()) && Boolean.TRUE.equals(source.isOriginEnabled())
            && !Boolean.TRUE.equals(source.isDetached());
    List<String> origins = source.getAllowedOrigins().map(value -> Arrays.stream(value.split(","))
        .map(String::trim).filter(v -> !v.isEmpty()).toList()).orElse(List.of());
    return new Source(source.getUid(), source.getCode(), source.getName().orElse(source.getCode()),
        source.getOriginType(), source.getIngestKey().orElse(null), accepting,
        source.getMinLevel().orElse("INFO"), source.getTraceSampleRate().orElse(100), origins,
        source.getRetentionDays(), ObserveSettings.keys(source.getScrubFields().orElse(null)));
  }
}
